selector_to_html = {"a[href=\"HeatExchangerResult.html#pyskyfire.heat_exchanger.solver.HeatExchangerResult\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.heat_exchanger.solver.HeatExchangerResult\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.heat_exchanger.solver.</span></span><span class=\"sig-name descname\"><span class=\"pre\">HeatExchangerResult</span></span></dt><dd></dd>", "a[href=\"CircuitResult.html#pyskyfire.heat_exchanger.solver.CircuitResult\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.heat_exchanger.solver.CircuitResult\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.heat_exchanger.solver.</span></span><span class=\"sig-name descname\"><span class=\"pre\">CircuitResult</span></span></dt><dd><p>One representative channel; heat_rate is TOTAL bank heat per segment.</p></dd>", "a[href=\"HeatExchanger.html#pyskyfire.heat_exchanger.solver.HeatExchanger\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.heat_exchanger.solver.HeatExchanger\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.heat_exchanger.solver.</span></span><span class=\"sig-name descname\"><span class=\"pre\">HeatExchanger</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">circuits</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">thermal_links</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">()</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">flow_connections</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">()</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>An assembly of banks, shared walls, and optional series headers.</p><p>Boundary mappings and inlet mappings use circuit names. For series banks,\nsupply an inlet only for the first bank. Thermal links may pair arbitrary\nsegment indices; exposed-area budgets prevent overlapping thermal links.\nA prescribed boundary heats whatever exposed area is not assigned a link.</p></dd>", "a[href=\"#module-pyskyfire.heat_exchanger.solver\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.heat_exchanger.solver<a class=\"headerlink\" href=\"#module-pyskyfire.heat_exchanger.solver\" title=\"Link to this heading\">\u00b6</a></h1><p>Steady single-phase heat exchange with conservative segment heat rates.</p><p>A circuit solution represents identical parallel copies. Static pressure obeys\nDarcy friction plus rho*u*du; energy conserves h + u\u00b2/2. Exchanger heat rates\nare iterated against segment midpoint states, including counterflow links.</p>", "a[href=\"WallResult.html#pyskyfire.heat_exchanger.solver.WallResult\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.heat_exchanger.solver.WallResult\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.heat_exchanger.solver.</span></span><span class=\"sig-name descname\"><span class=\"pre\">WallResult</span></span></dt><dd><p>One physical wall patch, with temperatures at both fluid interfaces.</p><p>Heat rate [W] is positive from b (or prescribed gas) into a, summed across\nthe bank. Area [m\u00b2] is per copied channel. Indices identify finite volumes.</p></dd>", "a[href=\"#classes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
